import{_ as l,a0 as i,w as p,s as d,ao as n,I as o,a1 as s,A as a,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 KDE Plasma 桌面进行屏幕共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 KDE Plasma 桌面进行屏幕共享 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 KDE Plasma 桌面进行屏幕共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 KDE Plasma 桌面进行屏幕共享 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220225 How to screen share with the Linux KDE Plasma Desktop","title":"如何在 KDE Plasma 桌面进行屏幕共享","tag":"202203","desc":""},"relativePath":"202203/20220225 How to screen share with the Linux KDE Plasma Desktop.md","filePath":"[post].md"}'),m={name:"202203/20220225 How to screen share with the Linux KDE Plasma Desktop.md"};function u(f,t,k,g,h,b){const r=i("Link");return p(),d("div",null,[t[19]||(t[19]=n('<h1 id="如何在-kde-plasma-桌面进行屏幕共享" tabindex="-1">如何在 KDE Plasma 桌面进行屏幕共享 <a class="header-anchor" href="#如何在-kde-plasma-桌面进行屏幕共享" aria-label="Permalink to “如何在 KDE Plasma 桌面进行屏幕共享”">​</a></h1><blockquote><p>krfb 和 krdc 的组合是使远程 Linux 支持变得无挫折感的宝贵工具。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/06/102407oi1sz113151dd5bw.jpg" alt=""></p><p>如果你曾经做过专业的或出于家庭义务的远程支持，在待命支持时，解决问题只是第二步，更重要的是可见用户屏幕上的实际内容。有多少次你描述了复杂的桌面任务，后来才发现你的用户甚至还没有打开他们的电脑？支持是重要的，但挫折感是真实的，对于需要支持的人和慷慨地试图提供支持的人来说，这都是一种共同的经历。我相信，作为学习新技能的一种方式，人们自己执行任务是很重要的，但也有一种说法是观察专家应该如何做。这就是屏幕共享的作用，KDE Plasma 桌面已经内置了它。</p><h3 id="网络安全" tabindex="-1">网络安全 <a class="header-anchor" href="#网络安全" aria-label="Permalink to “网络安全”">​</a></h3><p>Plasma 桌面使用点对点的邀请模式进行屏幕共享。用户启动一个应用，启动一个虚拟网络连接（VNC）服务器，这时，支持人员就可以远程查看甚至控制计算机。如果这听起来像是潜在的不安全，那是因为它可能就是，但有防火墙的干预。如果你是一个与你不在同一网络上的人的支持人员，那么你必须在屏幕共享工作之前建立一个从你的网络到你的用户的网络的安全通道。理想情况下，你会在紧急情况发生前完成这项工作。</p>',6)),o("ol",null,[o("li",null,[s(r,{href:"https://opensource.com/article/20/9/firewall"},{default:a(()=>[...t[0]||(t[0]=[e("配置用户的路由器",-1)])]),_:1}),t[1]||(t[1]=e("，将 VNC 端口（默认为 5900，但你可以使用任何你喜欢的端口）路由到他们的计算机。",-1))]),o("li",null,[s(r,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:a(()=>[...t[2]||(t[2]=[e("在用户的本地防火墙中打开一个服务",-1)])]),_:1}),t[3]||(t[3]=e("，允许 VNC 流量（在你在第一步中指定的端口）。",-1))])]),t[20]||(t[20]=n('<h3 id="远程邀请" tabindex="-1">远程邀请 <a class="header-anchor" href="#远程邀请" aria-label="Permalink to “远程邀请”">​</a></h3><p>为了启动屏幕共享会话，用户必须启动 <strong>krfb</strong>（表示 “KDE remote frame buffer”）应用。这将启动一个 VNC 服务器，并创建一个临时密码。</p><p><img src="https://opensource.com/sites/default/files/kde-krfb.jpg" alt="krfb" title="krfb"></p><p><strong>krfb</strong> 使用的默认端口是 5900，但如果你需要，可以在 <strong>krfb</strong> 设置中改变。不过，这可能是你想提前做的事情，这样你就可以避免向你的用户解释如何改变协议的端口。</p><h3 id="查看和控制" tabindex="-1">查看和控制 <a class="header-anchor" href="#查看和控制" aria-label="Permalink to “查看和控制”">​</a></h3><p>当这个窗口打开时，你可以使用你喜欢的 VNC 客户端通过 VNC 登录。KDE 有 <strong>krdc</strong>（表示 “KDE remote desktop client”）应用。在支持的计算机上，启动它并向它提供目标 IP 地址。当你被提示输入密码时，输入你正在连接的 <strong>krfb</strong> 会话中显示的密码。</p><p><img src="https://opensource.com/sites/default/files/kde-krdc-session.jpg" alt="Screen sharing with krdc" title="Screen sharing with krdc"></p><p>连接上后，你就可以看到你用户的屏幕，你可以在他们遵循你的指示时引导他们。如果他们在遵循你的指示方面有困难，那么你可以控制他们的鼠标，并演示如何做某事。默认情况下，<strong>krfb</strong>（即他们正在运行的应用）在将控制权交给你之前会征求他们的同意。</p><h3 id="帮助进行中" tabindex="-1">帮助进行中 <a class="header-anchor" href="#帮助进行中" aria-label="Permalink to “帮助进行中”">​</a></h3><p>能够看到你的用户所看到的东西可以加速故障排除，减少支持电话双方的挫折感。只要你事先为你的支持设置好网络，<strong>krfb</strong> 和 <strong>krdc</strong> 的组合对于指导新用户完成 Linux 桌面发现之旅的 Linux 专业人士来说是很有价值的工具。</p><hr>',11)),o("p",null,[t[5]||(t[5]=e("via: ",-1)),s(r,{href:"https://opensource.com/article/22/2/screen-share-linux-kde"},{default:a(()=>[...t[4]||(t[4]=[e("https://opensource.com/article/22/2/screen-share-linux-kde",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),s(r,{href:"https://opensource.com/users/seth"},{default:a(()=>[...t[6]||(t[6]=[e("Seth Kenlon",-1)])]),_:1}),t[11]||(t[11]=e(" 选题：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[7]||(t[7]=[e("lujun9972",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),s(r,{href:"https://github.com/geekpi"},{default:a(()=>[...t[8]||(t[8]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),s(r,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=e("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),s(r,{href:"https://linux.cn/"},{default:a(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const P=l(m,[["render",u]]);export{D as __pageData,P as default};
